INSERT INTO "geniuses" ("id", "name", "era", "domain", "summary") VALUES
('seed_0000000', 'Aristotle', '384–322 BC', 'Philosophy / logic', 'Built systematic knowledge by defining essences and tracing causes to first principles.'),
('seed_000000h', 'Mozart', '1756–1791', 'Music composition', 'Composed whole works in auditory imagination before writing a note.'),
('seed_000000y', 'Walt Disney', '1901–1966', 'Creativity / enterprise', 'Separated dreaming, planning and critiquing so they never fought.'),
('seed_000001d', 'Leonardo da Vinci', '1452–1519', 'Art / science / engineering', 'Practiced saper vedere — knowing how to truly see — and tested ideas against experience.'),
('seed_000001p', 'Nikola Tesla', '1856–1943', 'Invention / engineering', 'Built and ran machines entirely in his mind, watching them wear over time before building.'),
('seed_0000020', 'Albert Einstein', '1879–1955', 'Theoretical physics', 'Reasoned from vivid thought-experiments and demanded deep simplicity.'),
('seed_0000029', 'Charlie Munger', '1924–2023', 'Investing / judgment', 'Applied a latticework of mental models and inverted problems to avoid stupidity.'),
('seed_000002h', 'Steve Jobs', '1955–2011', 'Product / design', 'Fused technology with liberal arts and said no to almost everything.'),
('seed_000002p', 'Ray Dalio', 'b. 1949', 'Investing / systems', 'Turned painful mistakes plus reflection into explicit, testable principles and systems.'),
('seed_000002x', 'Peter Drucker', '1909–2005', 'Management / contribution', 'Asked what the situation requires and focused on contribution and effectiveness.'),
('seed_0000035', 'Sherlock Holmes', 'fictional (A. Conan Doyle)', 'Observation / deduction', 'Reasoned backward from minute observed detail to the only explanation that fits.'),
('seed_000003d', 'Sigmund Freud', '1856–1939', 'Psychology / psychoanalysis', 'Decoded the hidden structure beneath behavior from slips, dreams and associations.'),
('seed_000003l', 'Elon Musk', 'b. 1971', 'Engineering / enterprise', 'Reasoned from physical first principles and compressed iteration cycles brutally.'),
('seed_000003q', 'Jeff Bezos', 'b. 1964', 'Enterprise / decision-making', 'Optimized for the long term and for reversible, high-velocity decisions.'),
('seed_000003v', 'Muhammad Yunus', 'b. 1940', 'Social business / economics', 'Inverted economic assumptions to design enterprises that solve social problems.'),
('seed_0000040', 'Richard Feynman', '1918–1988', 'Physics / learning', 'Compiled complex theory down to plain, first-principles pictures anyone could follow.'),
('seed_0000045', 'John von Neumann', '1903–1957', 'Math / computing / game theory', 'Found the underlying axioms of any field and ported pure-math structure across domains.'),
('seed_000004a', 'Carl Friedrich Gauss', '1777–1855', 'Mathematics', 'Found symmetry and shortcuts that replaced brute computation with elegant structure.'),
('seed_000004f', 'Alexander von Humboldt', '1769–1859', 'Natural science / systems', 'Saw nature as one connected web and related multi-domain data on a single picture.'),
('seed_000004k', 'Michael Faraday', '1791–1867', 'Electromagnetism', 'Reasoned physics through vivid spatial intuition, ahead of the math that later formalized it.');
INSERT INTO "genius_strategies" ("id", "geniusId", "name", "description", "repSequence", "tote", "identity", "beliefs", "values", "capabilities", "highLeverage", "creativeProcess", "learningProcess", "feedbackProcess", "shadowPatterns", "failureModes", "installProtocol") VALUES
('seed_000000b', 'seed_0000000', 'Chain of First Causes', 'Define essence, classify, trace the four causes until reaching an irreducible principle.', '[{"step": 1, "system": "Ad", "description": "State precisely what it IS."}, {"step": 2, "system": "V", "description": "Place it in a hierarchy of kinds."}, {"step": 3, "system": "Ad", "description": "Ask the four causes; repeat ''why'' to a first principle."}]'::jsonb, '{"test": "Reached an irreducible cause?", "operate": "Ask ''why'' one level deeper.", "testExit": "Cause can''t be reduced.", "exit": "Treat as first principle."}'::jsonb, 'A systematic seeker of the order of things.', 'Reality is intelligible; knowledge can be organized.', 'Truth, logic, classification.', 'Definition, classification, causal reasoning.', 'Belief: reality is intelligible · Define terms before arguing', 'Build frameworks that organize a whole domain.', 'Observe → categorize → abstract → systematize.', 'Test claims against definitions and logical consistency.', 'Over-categorization; mistaking the map for the territory.', 'Premature systems built on untested premises.', '["Write a one-sentence essence-definition first.", "List the four causes explicitly.", "Keep asking ''why'' until you can''t."]'::jsonb),
('seed_000000s', 'seed_000000h', 'Auditory Whole-Composition', 'Hear themes internally, let them assemble into a complete work, feel its rightness, then transcribe.', '[{"step": 1, "system": "A", "description": "Let themes sound in the mind''s ear."}, {"step": 2, "system": "A", "description": "Allow them to combine into the whole, heard at once."}, {"step": 3, "system": "K", "description": "Feel whether the whole is alive; then transcribe."}]'::jsonb, '{"test": "Sounds complete and alive internally?", "operate": "Hear variations / let it assemble.", "testExit": "The whole ''sounds finished''.", "exit": "Write it down."}'::jsonb, 'A vessel through which complete music arrives.', 'The music already exists; I discover it.', 'Harmony, beauty, elegance.', 'Auditory imagination; holding large structures; felt ''rightness''.', 'Compose in the ear, not on paper · Trust the felt sense of completeness', 'Internal simulation then rapid transcription.', 'Saturate in masters'' works, then recombine internally.', 'Inner ear judges emotional impact and elegance.', 'Impatience with the merely technical; reliance on flow.', 'Skipping revision when the inner ear is fatigued.', '["Practice hearing music internally without an instrument.", "Plan a whole before recording details.", "Use the felt ''rightness'' check before committing."]'::jsonb),
('seed_0000018', 'seed_000000y', 'Dreamer–Realist–Critic', 'Imagine without limits, plan concretely, then critique the plan (never the dream).', '[{"step": 1, "system": "V", "description": "Dreamer: see the finished experience, no constraints."}, {"step": 2, "system": "K", "description": "Realist: act out what must physically happen, in order."}, {"step": 3, "system": "Ad", "description": "Critic: question the PLAN against the dream, never the dream."}]'::jsonb, '{"test": "Does the plan reproduce the dream?", "operate": "Revise the realist plan.", "testExit": "Feasible AND faithful.", "exit": "Commit and build."}'::jsonb, 'A storyteller who makes the impossible feel inevitable.', 'Everything begins as imagination; constraints are solvable.', 'Imagination, joy, experience.', 'Visualization, sequencing, targeted critique.', 'Identity: storyteller not administrator · Spatially separate the three positions', 'A three-role creative method — dreamer, realist, critic — separated in space.', 'Prototype experiences and watch real audiences.', 'Critic evaluates plan vs. dream; audience reaction is final.', 'Critic leaking into the dream; perfectionism.', 'Over-investing before the realist plan is sound.', '["Use three physical spots; only dream in spot 1.", "Act out the plan in first person in spot 2.", "In spot 3 critique only the plan; route fixes to spot 2."]'::jsonb),
('seed_000001l', 'seed_000001d', 'Saper Vedere & Dimostrazione', 'Observe exhaustively from many angles, connect by analogy, imagine, then test against experience.', '[{"step": 1, "system": "V", "description": "Observe in fine detail from multiple viewpoints."}, {"step": 2, "system": "K", "description": "Connect by analogy across domains."}, {"step": 3, "system": "Ad", "description": "Imagine, draw, then test against direct experience."}]'::jsonb, '{"test": "Matches reality from every angle?", "operate": "Observe again differently.", "testExit": "Confirmed by experience.", "exit": "Record the principle."}'::jsonb, 'A universal learner for whom art and science are one seeing.', 'Everything connects; experience is the only true test.', 'Curiosity, beauty, integration.', 'Microscopic observation; cross-domain analogy; experiment.', 'Observe before theorizing · Test by experience (dimostrazione)', 'Cross-domain synthesis driven by observation.', 'Observe → sketch → question → connect → experiment.', 'Direct experience over authority; the drawing reveals errors.', 'Endless curiosity; unfinished projects.', 'Starting more than can be completed; perfection delaying release.', '["Observe one thing 10 minutes before any conclusion.", "Force one cross-domain analogy.", "Verify against a real test, not authority."]'::jsonb),
('seed_000001w', 'seed_000001p', 'Full Mental Simulation', 'Construct the device in imagination, run it over simulated time to find faults, fix in the mind, build once.', '[{"step": 1, "system": "V", "description": "Construct the machine vividly and completely in mind."}, {"step": 2, "system": "K", "description": "Run it mentally; watch it operate and wear over time."}, {"step": 3, "system": "Ad", "description": "Diagnose and redesign in imagination; build only when flawless."}]'::jsonb, '{"test": "Runs flawlessly over simulated time?", "operate": "Fix the imagined fault, re-run.", "testExit": "No faults in extended mental operation.", "exit": "Build the physical device."}'::jsonb, 'An engineer whose mind is a complete laboratory.', 'The mind can simulate reality; a flaw found in imagination is free.', 'Precision, innovation, efficiency.', 'Photographic visualization; mental simulation; patience.', 'Run it in the mind before the world · Simulate wear over time', 'Full mental prototype before any material work.', 'Iterative mental refinement; learn from imagined failure.', 'Mental simulation is the test bench; reality confirms.', 'Over-attachment to the perfect mental model; neglect of commercial reality.', 'Delaying execution; ignoring funding/partners.', '["Simulate the whole system in your mind before building.", "Fast-forward to find failure modes over time.", "Iterate mentally until clean, then commit resources."]'::jsonb),
('seed_0000026', 'seed_0000020', 'Gedankenexperiment', 'Imagine a vivid physical scenario at the limits, follow its logic to a contradiction, and reformulate principles to resolve it.', '[{"step": 1, "system": "V", "description": "Picture a concrete scenario at a physical limit (riding a light beam)."}, {"step": 2, "system": "K", "description": "Feel/run the scenario; find where intuition breaks."}, {"step": 3, "system": "Ad", "description": "Reformulate the principle to remove the contradiction; check math."}]'::jsonb, '{"test": "Does a contradiction remain?", "operate": "Adjust the principle / imagine a sharper case.", "testExit": "Consistent and simpler than before.", "exit": "Formalize."}'::jsonb, 'A seeker of the simple laws behind appearances.', 'The universe is comprehensible and ultimately simple.', 'Truth, simplicity, independence.', 'Visual thought-experiments; combinatory play; tenacity.', 'Hold the question for years · Imagine, don''t just calculate', 'Combinatory play with images, then formalization.', 'Question accepted axioms; learn by re-deriving.', 'Internal consistency + experimental prediction.', 'Stubbornness against evidence (later QM).', 'Clinging to aesthetic preference over data.', '["Convert a problem into one vivid scenario at its limit.", "Find where common sense breaks.", "Change a premise, not the conclusion."]'::jsonb),
('seed_000002e', 'seed_0000029', 'Latticework & Inversion', 'Run a problem through many disciplines'' models and solve by inversion — avoid what guarantees failure.', '[{"step": 1, "system": "Ad", "description": "List the relevant models from several disciplines."}, {"step": 2, "system": "Ad", "description": "Invert: what would guarantee the worst outcome?"}, {"step": 3, "system": "K", "description": "Act only inside competence, with margin of safety."}]'::jsonb, '{"test": "Have I checked it against multiple models?", "operate": "Add a discipline''s model / invert again.", "testExit": "Decision survives inversion + models.", "exit": "Act, sized for safety."}'::jsonb, 'A learning machine who compounds judgment.', 'Avoiding stupidity beats seeking brilliance.', 'Rationality, honesty, patience.', 'Multidisciplinary models; inversion; circle of competence.', 'Study how things fail, then avoid that · Act only where your knowledge is genuinely deep', 'Recombine models across disciplines.', 'Read broadly daily; maintain checklists.', 'Long-horizon outcomes; pre-mortem via inversion.', 'Over-confidence outside competence.', 'Acting where you lack a model; ignoring base rates.', '["Before deciding, list models from 3 disciplines.", "Write the failure path and avoid it.", "Size positions for margin of safety."]'::jsonb),
('seed_000002m', 'seed_000002h', 'Taste & Subtraction', 'Start from the felt user experience, then ruthlessly remove until only the essential, beautiful core remains.', '[{"step": 1, "system": "K", "description": "Feel the whole user experience as a person, not an engineer."}, {"step": 2, "system": "V", "description": "See the simplest form that delivers it."}, {"step": 3, "system": "Ad", "description": "Cut everything non-essential; demand craftsmanship in the unseen."}]'::jsonb, '{"test": "Is anything non-essential left?", "operate": "Remove it / simplify the flow.", "testExit": "Only the essential, beautiful core remains.", "exit": "Ship."}'::jsonb, 'A curator of products at the intersection of tech and the humanities.', 'Design is how it works; focus means saying no.', 'Simplicity, craftsmanship, experience.', 'Aesthetic taste; empathy for the user; ruthless focus.', 'Start from the experience, not the feature · Subtract until it''s essential', 'Experience-first design, then aggressive subtraction.', 'Study great design across fields; prototype relentlessly.', 'Personal taste as proxy for the user; demos over specs.', 'Reality distortion; harshness with people.', 'Overriding valid data with ego; alienating collaborators.', '["Describe the experience before any feature.", "Cut the feature list in half.", "Polish what users never see."]'::jsonb),
('seed_000002u', 'seed_000002p', 'Mistakes Into Principles', 'Treat every painful mistake as data, extract a reusable principle, encode it as a rule, and let the rule act next time.', '[{"step": 1, "system": "K", "description": "Notice the pain of a mistake without ego-defense."}, {"step": 2, "system": "Ad", "description": "Reflect: what type of situation is this, what''s the principle?"}, {"step": 3, "system": "V", "description": "Write the rule; build it into a checklist/algorithm."}]'::jsonb, '{"test": "Have I extracted a reusable principle?", "operate": "Reflect deeper / seek dissent.", "testExit": "Principle encoded and testable.", "exit": "Apply the rule next time."}'::jsonb, 'A radically open systems-builder who learns from being wrong.', 'Reality + reflection compounds; ego and blind spots are the enemies.', 'Truth, transparency, evolution.', 'Radical open-mindedness; principle extraction; systematizing.', 'Separate ego from being right · Encode lessons as reusable rules', 'Systematize judgment into decision rules and ''machines''.', 'Mistake → principle → rule → backtest.', 'Believability-weighted dissent; track rules against outcomes.', 'Over-systematizing; analysis at the cost of warmth.', 'Treating people as machines; rule rigidity in novel regimes.', '["Keep a mistake → principle log.", "Convert each principle into an if-then rule.", "Invite the strongest opposing view before deciding."]'::jsonb),
('seed_0000032', 'seed_000002x', 'Contribution & Effectiveness', 'Start from ''what does this situation need and what can I contribute?'', concentrate on the few things that matter, and manage by results.', '[{"step": 1, "system": "Ad", "description": "Ask what the situation requires and where you can contribute."}, {"step": 2, "system": "V", "description": "See the few priorities that produce results; drop the rest."}, {"step": 3, "system": "K", "description": "Build on strengths; manage time to the priorities."}]'::jsonb, '{"test": "Am I working on the vital few?", "operate": "Abandon a non-priority / sharpen the question.", "testExit": "Effort aligns with results that matter.", "exit": "Execute and measure."}'::jsonb, 'A steward who turns knowledge into responsible contribution.', 'Effectiveness can be learned; results live outside the organization.', 'Responsibility, integrity, contribution.', 'Asking the right question; prioritization; managing strengths.', 'Ask ''what needs to be done?'' before ''what do I want?'' · Concentrate on the vital few', 'Frame the right question; design for contribution.', 'Feedback analysis: predict outcomes, compare, adjust.', 'Measure results outside the org; abandon what no longer serves.', 'Abstraction without execution.', 'Confusing activity with results; keeping sunk priorities.', '["Begin each week with ''what does this need?''", "Pick the vital few; abandon one thing.", "Do a feedback analysis on a past decision."]'::jsonb),
('seed_000003a', 'seed_0000035', 'Observation & Abduction', 'Saturate on micro-detail others ignore, generate candidate explanations, eliminate the impossible, keep the one that fits.', '[{"step": 1, "system": "V", "description": "Scan for tiny anomalies and details others overlook."}, {"step": 2, "system": "Ad", "description": "Generate every explanation the details could imply (abduction)."}, {"step": 3, "system": "Ad", "description": "Eliminate the impossible; retain the single consistent account."}]'::jsonb, '{"test": "Does one explanation fit ALL the details?", "operate": "Gather one more observation / eliminate a candidate.", "testExit": "Exactly one explanation survives.", "exit": "Declare the conclusion."}'::jsonb, 'A reasoning instrument who sees what others merely look at.', 'Everything leaves a trace; the obvious is usually unobserved.', 'Precision, detachment, truth.', 'Microscopic observation; abductive inference; elimination.', 'Observe, don''t just see · Eliminate the impossible; whatever remains is the truth', 'Reconstruct the whole from fragments by inference.', 'Build vast specialized reference knowledge (soils, tobaccos, hands).', 'Test the theory against new evidence; discard if contradicted.', 'Cold detachment; boredom without stimulation.', 'Over-confidence when data is thin; theorizing ahead of facts.', '["Spend the first minutes only observing details.", "List every explanation before choosing.", "Cross out the impossible; trust what remains."]'::jsonb),
('seed_000003i', 'seed_000003d', 'Decoding the Unconscious', 'Treat surface errors, dreams and free associations as data, trace them to latent structure, and surface the underlying pattern.', '[{"step": 1, "system": "A", "description": "Collect free associations, slips, dream fragments without censoring."}, {"step": 2, "system": "Ad", "description": "Interpret: what latent wish/conflict would produce this surface?"}, {"step": 3, "system": "K", "description": "Test the interpretation against the person''s felt response."}]'::jsonb, '{"test": "Does the interpretation resolve the surface anomalies?", "operate": "Gather more associations / revise the hypothesis.", "testExit": "Latent pattern accounts for the material.", "exit": "Make the unconscious conscious."}'::jsonb, 'An archaeologist of the mind reading what the surface conceals.', 'Nothing is accidental; the hidden drives the visible.', 'Insight, honesty about the self, depth.', 'Metacognition; symbolic interpretation; pattern-finding under the surface.', 'Read the slip, the dream, the omission as signal · Trace surface to latent cause', 'Build explanatory structures from fragmentary signals.', 'Case-by-case pattern accumulation; self-analysis.', 'Clinical response; later, falsifiability critiques.', 'Over-interpretation; unfalsifiable certainty.', 'Forcing one schema onto all cases; ignoring disconfirmation.', '["Note the slip/omission instead of dismissing it.", "Ask what hidden aim it would serve.", "Check the read against lived response, not theory alone."]'::jsonb),
('seed_000003o', 'seed_000003l', 'First Principles & Fast Iteration', 'Strip a problem to physics-level truths, rebuild the solution from there, then iterate hardware as fast as failure allows.', '[{"step": 1, "system": "Ad", "description": "Reduce to fundamental physical/economic truths."}, {"step": 2, "system": "V", "description": "Rebuild the solution upward from those truths."}, {"step": 3, "system": "K", "description": "Build, test to failure, iterate; delete parts/steps aggressively."}]'::jsonb, '{"test": "Is any constraint just convention, not physics?", "operate": "Remove the convention / rebuild from base truths.", "testExit": "Design is bounded only by physics & cost-floor.", "exit": "Build and iterate."}'::jsonb, 'An engineer who treats the impossible as an unsolved physics problem.', 'Reason up from physics, not analogy; cost/limits are usually conventions.', 'Truth, speed, leverage on civilization-scale problems.', 'First-principles decomposition; rapid iteration; extreme risk tolerance.', 'Reason from physics, not analogy · Make the cycle time short; let it fail fast', 'First-principles redesign + ruthless iteration loops.', 'Learn the underlying science directly; learn by destructive testing.', 'Reality (test stands, telemetry) over opinion; rapid retry.', 'Over-aggressive timelines; burnout of teams.', 'Underestimating integration time; spreading focus thin.', '["Write the physics floor of the problem.", "Rebuild ignoring how it''s ''normally'' done.", "Shorten the iteration cycle; delete before optimizing."]'::jsonb),
('seed_000003t', 'seed_000003q', 'Long-Horizon, Reversible-First', 'Anchor on the customer and a long horizon, classify decisions by reversibility, and decide fast on the reversible ones.', '[{"step": 1, "system": "Ad", "description": "Project to the long horizon; minimize future regret."}, {"step": 2, "system": "V", "description": "Write the customer outcome backward (the future press release)."}, {"step": 3, "system": "Ad", "description": "Classify: one-way (deliberate) vs two-way door (decide fast)."}]'::jsonb, '{"test": "Is this a reversible (two-way) door?", "operate": "If reversible, decide now; if not, gather more.", "testExit": "Decision matched to its reversibility.", "exit": "Act at the right speed."}'::jsonb, 'A long-term owner working backward from the customer.', 'Most decisions are reversible; speed compounds; obsess over customers not competitors.', 'Customer obsession, long-term thinking, high standards.', 'Working backward; decision-type classification; minimizing long-run regret.', 'Work backward from the customer · Two-way doors: decide fast and reverse if wrong', 'Work backward from the desired customer experience.', 'Narrative memos over slides; learn from disagree-and-commit.', 'Long-horizon metrics; customer signal over competitor noise.', 'Relentless standards straining people.', 'Treating one-way doors as two-way; over-expansion.', '["Write the future press release first.", "Label each decision one-way or two-way.", "Move fast on reversible calls; slow only on irreversible ones."]'::jsonb),
('seed_000003y', 'seed_000003v', 'Social Business Inversion', 'Question the assumptions that exclude the poor, invert them, and design a self-sustaining business whose objective is social good, not profit extraction.', '[{"step": 1, "system": "Ad", "description": "Name the accepted assumption that creates the exclusion."}, {"step": 2, "system": "Ad", "description": "Invert it and design from the excluded person''s reality."}, {"step": 3, "system": "K", "description": "Build a self-sustaining model; measure social impact, reinvest."}]'::jsonb, '{"test": "Does it sustain itself AND serve the social goal?", "operate": "Redesign the model / re-examine an assumption.", "testExit": "Self-sustaining and socially effective.", "exit": "Scale and replicate."}'::jsonb, 'An economist who designs systems for the excluded.', 'The poor are creditworthy; assumptions, not people, are the constraint.', 'Dignity, inclusion, sustainability.', 'Assumption inversion; bottom-up design; self-sustaining models.', 'Question the assumption that excludes people · Design for social objective, sustained by business', 'Invert economic orthodoxy; design ground-up.', 'Learn from the field/villages, not the textbook.', 'Repayment + measured social outcomes; iterate the model.', 'Idealism outrunning operational rigor.', 'Scaling before the model is genuinely self-sustaining.', '["Write the assumption that excludes your users.", "Design as if the opposite were true.", "Require the model to fund itself."]'::jsonb),
('seed_0000043', 'seed_0000040', 'The Feynman Technique', 'Strip the jargon, re-explain the idea in plain language and concrete images until the gap that reveals non-understanding is gone.', '[{"step": 1, "system": "Ad", "description": "State the concept; write it as if teaching a beginner."}, {"step": 2, "system": "V", "description": "Replace formal terms with concrete physical pictures (Feynman diagrams)."}, {"step": 3, "system": "Ad", "description": "Find where the explanation breaks; go relearn exactly that, repeat."}]'::jsonb, '{"test": "Can a first-year follow it with no jargon?", "operate": "Find the fuzzy spot, relearn it, re-explain.", "testExit": "Plain, gap-free explanation.", "exit": "You actually understand it."}'::jsonb, 'A relentless what-is-it-really child, never burdened by the authority pose.', 'Real understanding shows up as the ability to explain something plainly.', 'Honesty, clarity, curiosity, play.', 'Jargon-stripping; visual reframing; reasoning from basics.', 'Re-explain it for a beginner · Strip out the jargon on purpose', 'Reduce complexity to the simplest true picture, then rebuild.', 'Teach-to-learn; expose gaps by explaining aloud.', 'The listener''s confusion marks the exact gap to fix.', 'Impatience with pomposity; dismissiveness of formalism.', 'Oversimplifying past the point of accuracy.', '["Write the idea for a 1st-year student.", "Delete every piece of jargon; draw it.", "Relearn wherever the explanation stutters."]'::jsonb),
('seed_0000048', 'seed_0000045', 'Axiomatic Cross-Domain Modeling', 'Reduce a new field to its core axioms and mathematical structure, then attack it with deep general machinery from another field.', '[{"step": 1, "system": "Ad", "description": "Extract the field''s core conflict as a mathematical set/structure."}, {"step": 2, "system": "Ad", "description": "Map it to a known structure you already master (isomorphism)."}, {"step": 3, "system": "V", "description": "Apply your general machinery; formalize the result (e.g. game theory)."}]'::jsonb, '{"test": "Have I found the underlying axioms?", "operate": "Abstract one level higher / find the isomorphism.", "testExit": "Field reduced to known structure.", "exit": "Solve with general tools."}'::jsonb, 'A universal modeler who sees structure, not surface phenomena.', 'Behind any complex system lies a small set of base axioms.', 'Rigor, generality, power.', 'Abstraction; isomorphism-spotting; cross-field transfer.', 'See the isomorphism, not the phenomenon · Reduce a field to axioms first', 'Translate domain A''s structure to solve domain B.', 'Learn the axioms, skip the folklore.', 'Mathematical consistency + predictive power.', 'Detachment from messy human/ethical reality.', 'Over-abstraction that ignores context-specific constraints.', '["Write the new problem as a formal structure.", "Find an isomorphic structure you already know.", "Port your strongest tools across."]'::jsonb),
('seed_000004d', 'seed_000004a', 'Algorithm Restructuring', 'Refuse brute force; search the problem''s structure for symmetry and shortcuts that collapse the work.', '[{"step": 1, "system": "V", "description": "Look at the whole structure, not the linear steps (1+100, 2+99…)."}, {"step": 2, "system": "Ad", "description": "Spot the invariant/symmetry that repeats."}, {"step": 3, "system": "Ad", "description": "Recast the task as a closed-form shortcut (50 × 101)."}]'::jsonb, '{"test": "Is there still brute force in this?", "operate": "Hunt for a symmetry / closed form.", "testExit": "An elegant shortcut replaces the grind.", "exit": "Compute the easy way."}'::jsonb, 'A seeker of the elegant path, the ''Prince of Mathematics''.', 'There is almost always a structural shortcut; brute force is a failure of seeing.', 'Elegance, rigor, efficiency.', 'Pattern/symmetry recognition; algorithmic reframing; intuition.', 'Find the symmetry before computing · Refuse brute force', 'Compress computation into structure.', 'Re-derive from the cleanest possible angle.', 'Elegance + correctness; distrust ugly proofs.', 'Perfectionism; reluctance to publish the messy.', 'Withholding work until it''s flawless; slow dissemination.', '["Before computing, ask ''where''s the symmetry?''", "Look for a closed-form shortcut.", "Prefer the elegant solution over the powerful machine."]'::jsonb),
('seed_000004i', 'seed_000004f', 'Networked Ecological Thinking', 'Refuse to study a discipline in isolation; overlay climate, geology, biology and culture data to reveal universal cross-domain laws.', '[{"step": 1, "system": "V", "description": "Gather data across disciplines and regions onto one visual field (isotherms)."}, {"step": 2, "system": "Ad", "description": "Look for cross-domain correlations others miss (climate↔vegetation)."}, {"step": 3, "system": "Ad", "description": "Abstract the universal law from the relationships."}]'::jsonb, '{"test": "Have I connected enough domains to see the pattern?", "operate": "Add another data dimension / region.", "testExit": "A cross-domain regularity appears.", "exit": "State the general law."}'::jsonb, 'A connector who sees the web of life as one great whole.', 'Everything is interconnected; isolated study misses the real pattern.', 'Wholeness, wonder, rigor across domains.', 'Multi-modal data association; visualization; global pattern-finding.', 'Plot every domain on one chart · Compare across regions and dimensions', 'Synthesis across disciplines via visualization.', 'Field measurement + comparison across systems.', 'Cross-regional consistency of the pattern.', 'Breadth that risks losing depth.', 'Spreading across too much to finish synthesis.', '["Put data from 3+ domains on one chart.", "Hunt for cross-domain correlations.", "Generalize the relationship into a law."]'::jsonb),
('seed_000004n', 'seed_000004k', 'Spatial-Intuitive Modeling', 'When the math is out of reach, perceive the invisible physically — model fields as tangible, elastic lines you can feel in space.', '[{"step": 1, "system": "V", "description": "Picture the invisible phenomenon as concrete objects (taut elastic field lines)."}, {"step": 2, "system": "K", "description": "Feel how they push/pull and move in space."}, {"step": 3, "system": "Ad", "description": "Design an experiment to confirm the imagined model."}]'::jsonb, '{"test": "Does the physical picture predict the experiment?", "operate": "Adjust the imagined model, retest.", "testExit": "Model matches observation.", "exit": "Hand the intuition to the mathematicians (Maxwell)."}'::jsonb, 'A self-taught experimenter who trusts physical intuition over formalism.', 'Physical intuition can precede and guide the mathematics.', 'Curiosity, directness, humility, rigor in the lab.', '3D spatial imagination; physical analogy; meticulous experiment.', 'See the invisible as tangible (lines of force) · Let intuition lead the math', 'Visualize the unseen, then verify by experiment.', 'Hands-on experiment over formal training.', 'Experimental result confirms or kills the mental model.', 'Distrust of pure math may limit formal reach.', 'Insights stalling for lack of formalization.', '["Render the invisible as tangible objects in your mind.", "Feel how they''d move/interact.", "Design the experiment that would prove it."]'::jsonb);
INSERT INTO "identity_families" ("id", "slug", "name", "purpose", "sortOrder") VALUES
('seed_0000001', 'truth-seekers', 'Truth Seekers', 'Understand reality', 0),
('seed_000001i', 'creators', 'Creators', 'Create new realities', 1),
('seed_000002c', 'builders', 'Builders', 'Transform ideas into systems', 2),
