INSERT INTO "cog_biases" ("id", "slug", "name", "description", "correction") VALUES
('seed_000002b', 'confirmation-bias', 'Confirmation Bias', 'Seeking and weighting evidence that confirms what you already believe.', 'Actively seek disconfirming evidence; argue the other side.'),
('seed_000002d', 'sunk-cost-bias', 'Sunk Cost Bias', 'Continuing because of past investment rather than future value.', 'Decide from here forward; ignore unrecoverable costs.'),
('seed_000002g', 'authority-bias', 'Authority Bias', 'Over-weighting the opinion of an authority figure.', 'Judge the argument, not the title.'),
('seed_000002j', 'recency-bias', 'Recency Bias', 'Over-weighting the most recent events.', 'Zoom out to base rates and longer history.'),
('seed_000002l', 'availability-bias', 'Availability Bias', 'Judging likelihood by how easily examples come to mind.', 'Use actual frequencies, not vividness.'),
('seed_000002o', 'loss-aversion', 'Loss Aversion', 'Feeling losses roughly twice as strongly as equivalent gains.', 'Reframe in absolute terms; weigh symmetrically.'),
('seed_000002r', 'overconfidence', 'Overconfidence', 'Systematically overestimating your accuracy or control.', 'Track calibration; pre-mortem your plan.'),
('seed_000002t', 'status-quo-bias', 'Status Quo Bias', 'Preferring things to stay the same by default.', 'Ask: would I choose this fresh today?'),
('seed_000002w', 'social-proof-bias', 'Social Proof Bias', 'Copying the crowd instead of reasoning independently.', 'Separate consensus from correctness.'),
('seed_000002z', 'halo-effect', 'Halo Effect', 'Letting one positive trait color your whole judgment.', 'Evaluate each dimension on its own evidence.');
