('seed_0000037', 'economics', 'Economics', 'What are the costs, incentives and expected value?'),
('seed_0000039', 'probability', 'Probability', 'What''s likely, and how confident should I be?'),
('seed_000003c', 'systems', 'Systems', 'What are the second-order effects and feedback loops?'),
('seed_000003f', 'psychology', 'Psychology', 'What biases might be distorting this?'),
('seed_000003h', 'risk', 'Risk', 'What''s the downside, and can I survive being wrong?'),
('seed_000003k', 'time-horizon', 'Time Horizon', 'How does this look over years, not days?');
INSERT INTO "worldview_archetypes" ("id", "slug", "name", "mission", "coreAssumptions", "values", "blindSpots", "growthOpportunities") VALUES
('seed_0000003', 'explorer', 'Explorer', 'Discover what''s possible by venturing past the known.', ARRAY['Reality rewards the curious', 'The map is never the territory', 'Discovery beats certainty']::TEXT[], ARRAY['Curiosity', 'Courage', 'Openness']::TEXT[], ARRAY['Restlessness', 'Starting more than finishing']::TEXT[], ARRAY['Pair exploration with one committed depth']::TEXT[]),
('seed_0000008', 'builder', 'Builder', 'Turn possibility into working reality.', ARRAY['Reality is shaped by what we make', 'Shipping reveals truth']::TEXT[], ARRAY['Craft', 'Pragmatism', 'Reliability']::TEXT[], ARRAY['Building before deciding what matters']::TEXT[], ARRAY['Add a ''why'' check before each build']::TEXT[]),
('seed_000000e', 'scholar', 'Scholar', 'Understand reality deeply before acting.', ARRAY['Knowledge compounds', 'Context determines meaning']::TEXT[], ARRAY['Depth', 'Rigor', 'Patience']::TEXT[], ARRAY['Analysis without action', 'Detachment']::TEXT[], ARRAY['Set action deadlines on inquiry']::TEXT[]),
('seed_000000k', 'entrepreneur', 'Entrepreneur', 'Create value by acting under uncertainty.', ARRAY['Uncertainty is opportunity', 'Value created beats credentials']::TEXT[], ARRAY['Initiative', 'Resilience', 'Focus']::TEXT[], ARRAY['Chasing too many opportunities']::TEXT[], ARRAY['Adopt a single-focus filter']::TEXT[]),
('seed_000000p', 'guardian', 'Guardian', 'Protect and preserve what matters.', ARRAY['Some things must be defended', 'Stability enables growth']::TEXT[], ARRAY['Duty', 'Prudence', 'Loyalty']::TEXT[], ARRAY['Resisting needed change', 'Over-caution']::TEXT[], ARRAY['Distinguish protecting from clinging']::TEXT[]),
('seed_000000v', 'visionary', 'Visionary', 'See and call forth a better future.', ARRAY['The future is built by those who imagine it', 'Meaning aligns people']::TEXT[], ARRAY['Imagination', 'Conviction', 'Hope']::TEXT[], ARRAY['Detachment from reality', 'Vision without execution']::TEXT[], ARRAY['Pair each vision with a realist plan']::TEXT[]),
('seed_0000011', 'strategist', 'Strategist', 'Win by choosing where and how to act.', ARRAY['Position beats effort', 'Most outcomes are decided before the contest']::TEXT[], ARRAY['Foresight', 'Discipline', 'Focus']::TEXT[], ARRAY['Over-planning', 'Cynicism']::TEXT[], ARRAY['Convert one plan into action this week']::TEXT[]),
('seed_0000016', 'creator', 'Creator', 'Bring new realities into being.', ARRAY['Creation is a discipline', 'Constraints breed originality']::TEXT[], ARRAY['Originality', 'Courage', 'Expression']::TEXT[], ARRAY['Perfectionism', 'Comparison']::TEXT[], ARRAY['Ship before it feels ready']::TEXT[]),
('seed_000001b', 'systems-thinker', 'Systems Thinker', 'See the whole, its relationships and feedback.', ARRAY['Everything is connected', 'Structure drives behavior']::TEXT[], ARRAY['Holism', 'Patience', 'Leverage']::TEXT[], ARRAY['Over-modeling', 'Paralysis from complexity']::TEXT[], ARRAY['Act on the highest-leverage point now']::TEXT[]),
('seed_000001g', 'legacy-builder', 'Legacy Builder', 'Create impact that outlives the self.', ARRAY['The best work outlives its maker', 'We inherit and pass on']::TEXT[], ARRAY['Stewardship', 'Long-term thinking', 'Significance']::TEXT[], ARRAY['Neglecting the present', 'Legacy obsession']::TEXT[], ARRAY['Balance long arc with present contribution']::TEXT[]);
INSERT INTO "audiobooks" ("id", "slug", "title", "author", "relatedModule", "inspiredByNote", "summary", "textContent", "sourceType", "format", "isPublicDomain") VALUES
('seed_0000004', 'strategies-of-genius', 'Strategies of Genius (concept)', 'R. Dilts (idea)', 'Genius Library', 'Inspired by the general idea of modeling how exceptional people think.', 'An exploration of how to model the thinking patterns, beliefs and strategies of exceptional individuals so others can learn them.', '', 'CATALOG', 'TEXT', false),
('seed_0000009', 'from-coach-to-awakener', 'From Coach to Awakener (concept)', 'R. Dilts (idea)', 'Leadership Leverage', 'Inspired by the idea of leadership across logical levels.', 'Frames leadership as a progression of roles — caretaker, guide, coach, mentor, sponsor, awakener — each operating at a higher leverage level.', '', 'CATALOG', 'TEXT', false),
('seed_000000f', 'high-output-management', 'High Output Management (concept)', 'A. Grove (idea)', 'Management OS', 'Inspired by the idea of managerial leverage.', 'Treats a manager''s output as the output of their team and argues for spending time on the highest-leverage activities.', '', 'CATALOG', 'TEXT', false),
('seed_000000l', 'the-effective-executive', 'The Effective Executive (concept)', 'P. Drucker (idea)', 'Management OS', 'Inspired by the idea of effectiveness and contribution.', 'Argues effectiveness is a learnable discipline: focus on contribution, concentrate on the vital few, and build on strengths.', '', 'CATALOG', 'TEXT', false),
('seed_000000q', 'the-knowledge-creating-company', 'The Knowledge-Creating Company (concept)', 'I. Nonaka (idea)', 'Management OS', 'Inspired by the SECI tacit-knowledge idea.', 'Describes how organizations convert tacit individual knowledge into explicit shared assets through cycles of socialization, externalization, combination and internalization.', '', 'CATALOG', 'TEXT', false),
('seed_000000w', 'antifragile', 'Antifragile (concept)', 'N. Taleb (idea)', 'Cognitive OS', 'Inspired by the idea of gaining from disorder.', 'Distinguishes the fragile, the robust and the antifragile — systems that improve under stress and volatility.', '', 'CATALOG', 'TEXT', false),
('seed_0000012', 'thinking-fast-and-slow', 'Thinking, Fast and Slow (concept)', 'D. Kahneman (idea)', 'Cognitive OS', 'Inspired by the idea of two systems of thinking and cognitive bias.', 'Contrasts fast intuitive thinking with slow deliberate reasoning and catalogs the biases that distort judgment.', '', 'CATALOG', 'TEXT', false),
('seed_0000017', 'poor-charlies-almanack', 'Poor Charlie''s Almanack (concept)', 'C. Munger (idea)', 'Cognitive OS', 'Inspired by the latticework-of-models idea.', 'Advocates building a latticework of mental models from many disciplines and reasoning by inversion to avoid error.', '', 'CATALOG', 'TEXT', false),
('seed_000001c', 'good-strategy-bad-strategy', 'Good Strategy Bad Strategy (concept)', 'R. Rumelt (idea)', 'Cognitive OS', 'Inspired by the idea of diagnosis-first strategy.', 'Argues good strategy starts with an honest diagnosis, a guiding policy, and coherent action — not goals and slogans.', '', 'CATALOG', 'TEXT', false),
('seed_000001h', 'mindset', 'Mindset (concept)', 'C. Dweck (idea)', 'Genius Kids', 'Inspired by the growth-mindset idea.', 'Contrasts a fixed mindset (ability is static) with a growth mindset (ability grows with effort and strategy).', '', 'CATALOG', 'TEXT', false),
('seed_000001k', 'the-montessori-method', 'The Montessori Method', 'M. Montessori', 'Genius Kids', 'Public-domain text; inspired the prepared-environment idea.', 'An early account of child-led learning in a carefully prepared environment that supports independence and concentration.', 'The Montessori Method emphasizes preparing an environment in which the child can act, choose and concentrate freely. The adult''s role is to observe and to remove obstacles, not to direct every action. When children are given freedom within thoughtful limits, they reveal a deep capacity for self-directed work and joyful concentration.', 'PUBLIC_DOMAIN', 'TEXT', true),
('seed_000001o', 'the-nicomachean-ethics', 'The Nicomachean Ethics', 'Aristotle', 'Worldview OS', 'Public-domain; inspired the first-causes and virtue ideas.', 'A foundational inquiry into the good life, virtue as a mean between extremes, and happiness as activity of the soul in accordance with virtue.', 'Every art and every inquiry, and similarly every action and pursuit, is thought to aim at some good; and for this reason the good has rightly been declared to be that at which all things aim. Virtue, then, is a state of character concerned with choice, lying in a mean relative to us.', 'PUBLIC_DOMAIN', 'TEXT', true),
('seed_000001s', 'the-adventures-of-sherlock-holmes', 'The Adventures of Sherlock Holmes', 'A. Conan Doyle', 'Genius Library', 'Public-domain; inspired the observation-and-deduction model.', 'Detective stories illustrating disciplined observation of detail and reasoning from evidence to the single explanation that fits.', 'It is a capital mistake to theorize before one has data. Insensibly one begins to twist facts to suit theories, instead of theories to suit facts. The world is full of obvious things which nobody by any chance ever observes.', 'PUBLIC_DOMAIN', 'TEXT', true),
('seed_000001v', 'the-notebooks-of-leonardo-da-vinci', 'The Notebooks of Leonardo da Vinci', 'Leonardo da Vinci', 'Genius Library', 'Public-domain; inspired saper-vedere observation.', 'Leonardo''s collected observations on art, nature, anatomy and engineering — a model of learning to truly see and testing ideas against experience.', 'Experience does not err; only your judgments err by expecting from her what is not in her power. Learn how to see. Realize that everything connects to everything else.', 'PUBLIC_DOMAIN', 'TEXT', true),
('seed_000001z', 'the-art-of-war', 'The Art of War', 'Sun Tzu', 'Cognitive OS', 'Public-domain; inspired strategic positioning.', 'An ancient treatise on strategy: win by position, timing and knowing both yourself and the situation before the contest begins.', 'If you know the enemy and know yourself, you need not fear the result of a hundred battles. The supreme art of war is to subdue the enemy without fighting.', 'PUBLIC_DOMAIN', 'TEXT', true),
('seed_0000023', 'meditations', 'Meditations', 'Marcus Aurelius', 'Worldview OS', 'Public-domain; inspired reflection and responsibility.', 'Private notes of a Roman emperor on self-discipline, responsibility, and living according to reason and nature.', 'You have power over your mind — not outside events. Realize this, and you will find strength. The happiness of your life depends upon the quality of your thoughts.', 'PUBLIC_DOMAIN', 'TEXT', true);
